const { existsSync, readFileSync } = require('fs')
const { join } = require('path')

const { platform, arch } = process

let nativeBinding = null
let loadError = null

function isMusl() {
  // For Node 12+, detect musl via process.report
  if (!process.report || typeof process.report.getReport !== 'function') {
    try {
      const lddPath = require('child_process').execSync('which ldd').toString().trim()
      return readFileSync(lddPath, 'utf8').includes('musl')
    } catch {
      return true
    }
  } else {
    const { glibcVersionRuntime } = process.report.getReport().header
    return !glibcVersionRuntime
  }
}

switch (platform) {
  case 'darwin':
    switch (arch) {
      case 'x64':
        try {
          nativeBinding = require('mast-memory-darwin-x64')
        } catch (e) {
          loadError = e
        }
        break
      case 'arm64':
        try {
          nativeBinding = require('mast-memory-darwin-arm64')
        } catch (e) {
          loadError = e
        }
        break
      default:
        throw new Error(`Unsupported architecture on macOS: ${arch}`)
    }
    break
  case 'linux':
    switch (arch) {
      case 'x64':
        if (isMusl()) {
          try {
            nativeBinding = require('mast-memory-linux-x64-musl')
          } catch (e) {
            loadError = e
          }
        } else {
          try {
            nativeBinding = require('mast-memory-linux-x64-gnu')
          } catch (e) {
            loadError = e
          }
        }
        break
      case 'arm64':
        try {
          nativeBinding = require('mast-memory-linux-arm64-gnu')
        } catch (e) {
          loadError = e
        }
        break
      default:
        throw new Error(`Unsupported architecture on Linux: ${arch}`)
    }
    break
  default:
    throw new Error(`Unsupported OS: ${platform}, architecture: ${arch}`)
}

// Fallback: try loading local .node file (for development)
if (!nativeBinding) {
  const localFile = join(__dirname, 'mast.node')
  if (existsSync(localFile)) {
    nativeBinding = require(localFile)
  }
}

if (!nativeBinding) {
  if (loadError) {
    throw loadError
  }
  throw new Error('Failed to load native binding')
}

const { MastDb } = nativeBinding

module.exports.MastDb = MastDb
